import { Component } from 'react'
import { connect } from 'react-redux'
import { Container, ContentBox, Button } from '../../../../../components'
import { WithdrawalHistoryWrapper } from '../../container/index.style'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import WalletActions from '../../../../../redux/transaction/action'
import { formatMoney, isCreditAmount } from '../../../../../helpers/utility'

const { getWithdrawalList } = WalletActions

class WithdrawalHistory extends Component {
  constructor (props) {
    super(props)
    this.state = {
      pageNumber: 1
    }
  }

  componentDidMount () {
    this.props.getWithdrawalList({ page_size: 5 })
  }

  handleLoadMore = () => {
    const { pageNumber } = this.state
    this.props.getWithdrawalList({ page_size: (pageNumber + 1) * 5 })
    this.setState({ pageNumber: pageNumber + 1 })
  }

  render () {
    const { withdrawalListLoading, withdrawalList = {} } = this.props
    const { pageNumber } = this.state

    return (
      <Container title='Mutasi Tarik Saldo'>
        <WithdrawalHistoryWrapper loader={withdrawalListLoading}>
          {
            withdrawalList.data && withdrawalList.data.map((transaction, index) =>
              <ContentBox
                heading={transaction.commission_type}
                value={isCreditAmount(transaction.amount) ? '+ ' + formatMoney(transaction.amount, 0) : formatMoney(transaction.amount, 0)}
                secondRowText={transaction.description}
                thirdRowText={transaction.transaction_date}
                color={isCreditAmount(transaction.amount) ? AgentColorPallette.green : AgentColorPallette.error}
                key={index}
                type='WITHDRAWAL'
              />
            )
          }
          {
            withdrawalList.meta_data && withdrawalList.meta_data.total_records > (pageNumber * 5) &&
              <Button className='button-load' onClick={this.handleLoadMore}>
                {'TAMPILKAN LAGI'}
              </Button>
          }
        </WithdrawalHistoryWrapper>
      </Container>
    )
  }
}

export default connect((state) => ({
  withdrawalListLoading: state.Loading.GET_WITHDRAWAL_LIST,
  withdrawalList: state.Transaction.withdrawalList
}), {
  getWithdrawalList
})(WithdrawalHistory)
